import{_ as l,c as r,o as t,ag as e}from"./chunks/framework.Bkod66qp.js";const b=JSON.parse('{"title":"문예지원사업 지원금 관리규정","description":"","frontmatter":{"title":"문예지원사업 지원금 관리규정","subtitle":"","doc_id":"","last_update":"2018-03-23","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/701_문예지원사업 지원금 관리규정(180323).md","filePath":"regulation/701_문예지원사업 지원금 관리규정(180323).md"}'),i={name:"regulation/701_문예지원사업 지원금 관리규정(180323).md"};function o(s,a,n,c,d,h){return t(),r("div",null,a[0]||(a[0]=[e(`<h1 id="law-title" class="center" tabindex="-1">문예지원사업 지원금 관리규정 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;문예지원사업 지원금 관리규정 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2004.   3.  12
개정 2005.   3.  29
개정 2008.   6.  30
개정 2009.   9.   8
개정 2018.   3.  23</pre></div><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 규정은 재단법인서울문화재단(이하“재단”이라 한다)의 재원으로 하는 문화예술지원사업의 지원금의 교부대상ㆍ교부방법 및 사용 등에 관하여 필요한 사항을 규정함을 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (정의) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (정의) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(정의)</strong> 이 규정에서 사용하는 용어의 정의는 다음 각 호와 같다.</p><ol><li>&quot;지원금&quot;이라 함은 재단 외의 자가 행하는 사무 또는 사업에 대하여 공익상ㆍ정책상의 필요에 따라 문화예술사업에 재정상의 지원을 하기 위하여 재단에서 교부하는 자금을 말한다.</li><li>&quot;지원사업&quot;이라 함은 지원금의 교부대상이 되는 사무 또는 사업을 말한다.</li><li>&quot;지원사업자&quot;라 함은 지원사업을 수행하는 자를 말한다.</li></ol><h2 id="article3" class="sr-only" tabindex="-1">제3조 (다른 법령과의 관계) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (다른 법령과의 관계) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(다른 법령과의 관계)</strong> 지원금의 관리에 관하여는 다른 법령이나 규정에 특별히 정하는 것을 제외하고는 이 규정이 정하는 바에 의한다.</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (지원대상) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (지원대상) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(지원대상)</strong> 재단 대표이사는 다음 각호의 1에 해당하는 경우에 한하여 그 사업에 필요한 경비의 일부 또는 전부를 보조할 수 있다.</p><ol><li>법률이나 규정에 있는 경우</li><li>서울특별시 재단법인 서울문화재단 설립 및 운영에 관한 조례 제3조 및 재단법인 서울문화재단 정관 제4조에서 규정한 사업과 활동 &lt;개정 2009. 9. 8.&gt;</li><li>국가나 시가 권장하는 사업을 위하여 필요하다고 인정되는 경우</li><li>재단 대표이사가 필요하다고 인정하는 사업</li></ol><h2 id="article5" class="sr-only" tabindex="-1">제5조 (지원신청) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (지원신청) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(지원신청)</strong> ① 지원금의 교부를 받고자 하는 자는 다음 사항을 기재한 지원사업 신청서를 재단에 제출하여야 한다.</p><ol><li>신청인의 성명 또는 명칭과 주소</li><li>지원사업의 목적과 내용</li><li>지원사업에 소요되는 총 경비와 교부 받고자 하는 금액</li><li>자기자본 부담액</li><li>지원사업기간</li><li>기타 지원금 신청에 필요한 사항<br> ② 제1항의 신청서에 필요한 사항은 재단 대표이사가 따로 정한다.</li></ol><h2 id="article6" class="sr-only" tabindex="-1">제6조 (지원금의 교부 결정) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (지원금의 교부 결정) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(지원금의 교부 결정)</strong> ① 재단 대표이사는 제5조의 규정에 의한 지원사업 신청서를 받은 때에는 다음 각호의 사항을 조사ㆍ검토하여 지원금의 교부여부를 결정한다.</p><ol><li>법령과 규정의 목적에 위배 여부</li><li>지원사업 내용의 적정 여부</li><li>금액산정의 착오 유무</li><li>자기자금의 부담능력 유무(사업자금의 일부를 보조하는 경우에 한한다)</li><li>신청인이 성희롱, 성폭력 등의 사유로 기소 중이거나 형 집행 중인지 여부 &lt;신설 2018. 3. 23.&gt;</li><li>기타 재단의 사업목적의 달성을 위한 적정성 여부<br> ② 제1항의 지원금 교부결정시 별도의 심의위원회를 운영하여 교부여부를 결정할 수 있으며, 심의위원회의 운영에 필요한 사항은 재단 대표이사가 따로 정할 수 있다. &lt;개정 2008. 6. 30.&gt;</li></ol><h2 id="article7" class="sr-only" tabindex="-1">제7조 (지원금의 교부조건) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (지원금의 교부조건) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(지원금의 교부조건)</strong> ① 재단 대표이사는 지원금의 교부를 결정함에 있어서 지원금액에 상당하는 자체 부담과 법령 및 규정이 정하는 지원금의 교부 목적 달성에 필요하다고 인정되는 조건을 붙일 수 있다.<br> ② 지원금을 교부받은 사업자가 지원금의 교부 목적 이외에 사용할 때에는 지원금의 전부 또는 일부에 해당하는 금액을 재단에 반환하게 하는 조건을 붙일 수 있다.<br> ③ 지원사업으로 인해 발생하는 수입금은 교부 목적에 부합하는 사업 외에는 사용할 수 없다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (지원금의 교부결정통지) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (지원금의 교부결정통지) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(지원금의 교부결정통지)</strong> ① 재단 대표이사는 제6조의 규정에 의하여 지원금의 교부를 결정하였을 때에는 지체 없이 그 결정내용과 조건을 기재한 교부통지서를 지원사업 신청인에게 발부하여야 한다.<br> ② 지원금의 교부결정 통지 전에 시행한 사업에 대하여는 지원금을 교부하지 아니한다. 다만, 특별한 사정에 의하여 재단 대표이사의 승인을 얻은 경우에는 그러하지 아니하다.</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (지원금의 교부) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (지원금의 교부) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(지원금의 교부)</strong> 지원금의 지급은 지원사업자의 교부신청에 의해 교부하며, 지원시기 및 지원금의 규모는 재단 대표이사가 따로 정한다.</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (사정변경에 의한 교부결정의 변경ㆍ취소) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (사정변경에 의한 교부결정의 변경ㆍ취소) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(사정변경에 의한 교부결정의 변경ㆍ취소)</strong> ① 재단 대표이사는 지원금의 교부결정 후에라도 사정 변경으로 인하여 특히 필요하다고 인정되는 경우에는 지원금의 교부결정내용과 조건을 변경하거나 교부결정의 전부 또는 일부를 취소할 수 있다.<br> ② 재단 대표이사가 제1항의 규정에 의하여 지원금의 교부결정을 취소할 수 있는 경우에는 다음 각호의 경우에 한한다.</p><ol><li>천재지변 또는 기타 이에 준하는 사유로 지원사업의 전부 또는 일부를 계속할 필요가 없는 경우</li><li>지원사업에 소요되는 경비 중 지원금 등으로 충당되는 부분 외의 경비(보조사업자가 부담하는 경비)를 조달하지 못하는 경우</li><li>지원사업자가 교부받은 지원금을 다른 용도에 사용하거나, 제7조의 내용과 조건을 위반한 경우</li><li>지원금의 교부내용을 허위로 신청한 경우</li><li>기타 사업의 목적에 위배되거나 부정한 방법으로 지원금을 교부 받은 경우<br> ③ 제1항에 의해 교부결정이 취소되었을 때에는 그 취소된 부분의 지원금을 반환 받아야 한다.</li></ol><h2 id="article11" class="sr-only" tabindex="-1">제11조 (용도 외 사용금지) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (용도 외 사용금지) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(용도 외 사용금지)</strong> 지원사업자는 법령 및 규정, 지원금 교부결정의 내용 및 조건에 따라 선량한 관리자의 주의로 성실히 보조사업을 수행하여야 하며, 그 지원금을 다른 용도에 사용하여서는 아니 된다.</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (지원사업의 내용변경 등) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (지원사업의 내용변경 등) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(지원사업의 내용변경 등)</strong> ① 지원사업자는 사정의 변경으로 지원사업의 내용 또는 지원사업에 소요되는 경비의 배분을 변경하거나 지원사업을 인계ㆍ중계 또는 폐지하고자 할 때에는 미리 재단 대표이사의 승인을 얻어야 한다.<br> ② 제1항의 규정에 의하여 지원사업을 승계한 자는 지원금을 받을 수 있다.</p><h2 id="article13" class="sr-only" tabindex="-1">제13조 (지원사업의 실적보고) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (지원사업의 실적보고) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(지원사업의 실적보고)</strong> 지원사업자는 사업을 완료하거나 폐지의 승인을 얻은 때에는 그 지원사업의 실적보고서, 사업비 정산서, 정산증빙서류를 재단 대표이사에게 제출하여야 한다. 단, 대표이사가 정하는 금액 이하의 소액지원 사업은 사업비 정산증빙서류 제출을 생략할 수 있다. &lt;개정 2005. 3. 29., 2008. 6. 30.&gt;</p><h2 id="article14" class="sr-only" tabindex="-1">제14조 (지원사업 정산검사 및 평가) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (지원사업 정산검사 및 평가) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(지원사업 정산검사 및 평가)</strong> ① 재단 대표이사는 제13조의 실적보고서와 사업비 정산서를 지원사업자로부터 제출받아 정산검사를 한다. 다만, 정산검사에 따른 현장확인이 필요하다고 인정하는 경우에는 소속직원을 현지에 출장시켜 그 내용을 확인하게 할 수 있다.<br> ② 재단 대표이사는 지원사업 기간 중 지원금의 적정한 집행을 기하기 위하여 필요하다고 인정할 때에는 지원사업자에 대하여 지원사업에 관한 보고를 하게 하거나 소속 직원으로 하여금 관계장부ㆍ서류 또는 그 사업내용을 검사하게 할 수 있다.<br> ③ 지원사업의 교부 목적과 기대효과를 위하여 지원사업에 관하여 평가하여야 한다.<br> ④ 제3항의 평가방법 및 절차에 대해서는 재단 대표이사가 따로 정하는 바에 의한다.</p><h2 id="article15" class="sr-only" tabindex="-1">제15조 (지원사업의 신고) <a class="header-anchor" href="#article15" aria-label="Permalink to &quot;제15조 (지원사업의 신고) {#article15 .sr-only}&quot;">​</a></h2><p><strong>제15조(지원사업의 신고)</strong> 지원금의 교부를 받은 자는 다음 각호의 1에 해당하는 사유가 발생한 때에는 15일 내에 재단 대표이사에게 신고하여야 한다.</p><ol><li>사업을 폐지한 때</li><li>사업의 명칭 또는 주소를 변경한 때</li><li>사업수행단체가 해산 또는 파산한 때</li></ol><h2 id="article16" class="sr-only" tabindex="-1">제16조 (지원사업자에 대한 제재) <a class="header-anchor" href="#article16" aria-label="Permalink to &quot;제16조 (지원사업자에 대한 제재) {#article16 .sr-only}&quot;">​</a></h2><p><strong>제16조(지원사업자에 대한 제재)</strong> 재단 대표이사는 지원사업자가 다음 각호의 1에 해당한다고 인정되는 때에는 지원금의 교부를 취소하거나 이미 교부한 지원금의 전부 또는 일부의 반환을 명할 수 있다.</p><ol><li>법령 또는 교부조건을 위반한 때</li><li>지원사업의 목표 달성이 어렵다고 인정되는 때</li><li>사업의 전부 또는 일부를 정지한 때</li><li>허위 또는 부정한 방법으로 지원금을 교부 받은 때</li><li>이 규정에 의한 의무나 처분을 이행하지 아니하거나 정산, 평가를 거부한 때 또는 허위 보고를 한 때</li><li>신청인이 성희롱, 성폭력 등의 사유로 기소 중이거나 형 집행 중일 때 &lt;신설 2018. 3. 23.&gt;</li><li>제10조의 각항에 해당된 때</li></ol><h2 id="article17" class="sr-only" tabindex="-1">제17조 (위임규정) <a class="header-anchor" href="#article17" aria-label="Permalink to &quot;제17조 (위임규정) {#article17 .sr-only}&quot;">​</a></h2><p><strong>제17조(위임규정)</strong> 이 규정 시행에 관하여 필요한 사항은 대표이사가 따로 정한다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 제1조(시행일) 이 규정은 2004년 3월 12일부터 시행한다.<br> 제2조(경과조치) 이 규정 시행 전에 서울특별시 방침에 의해 시행된 사항은 이 규정에 의하여 처리된 것으로 본다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2005. 3. 29.&gt;<br> 이 규정은 2005년 3월 29일부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2008. 6. 30.&gt;<br> 이 규정은 2008년 6월 30일부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2009. 9. 8.&gt;<br> 이 규정은 2009년 9월 8일부터 시행한다.</p><h2 id="addendum5" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum5" aria-label="Permalink to &quot;부칙 {#addendum5 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2018. 3. 23.&gt;<br> 이 규정은 2018년 3월 23일부터 시행한다.</p>`,53)]))}const g=l(i,[["render",o]]);export{b as __pageData,g as default};
